-- 衡枢真信授信与模拟供应商。由 example-data 导入器在一笔事务中执行，下列命令由服务端生成目标环境审批快照、签名和制品。
-- 来源为两个项目正在使用的已发布版本；不含运行记录、操作历史、控制台账号或源环境凭据。
SET @example_guard = CAST(IF(@credit_example_loader = 1,'true','USE_THE_EXAMPLE_DATA_LOADER') AS JSON);

-- 项目、函数及基础字段
SET @example_global_guard = CAST(IF(EXISTS(SELECT var_code FROM rule_variable WHERE scope='GLOBAL' AND var_code IN ('DECISION_PASS','DECISION_REJECT','DECISION_REVIEW','EMPTY_LIST','EMPTY_MAP','EMPTY_STRING','FALSE_VALUE','NEGATIVE_INFINITY','NEGATIVE_ONE','NULL_VALUE','ONE','POSITIVE_INFINITY','TRUE_VALUE','ZERO','create_time','credit_limit','credit_period','current_overdue_days','device_id','gps_latitude','gps_longitude','idcard_expiry_date','idcard_no','mobile_no','name','request_id','result','trace_id') GROUP BY var_code HAVING COUNT(*)>1),'AMBIGUOUS_GLOBAL_VARIABLE','true') AS JSON);
